FString AIStudioBridgeLibrary::SynthesizeNiagaraSourceStrategyStack(FString system_path, FString source_strategy, TMap<FString, FString> parameters, bool save)
{
    UNREAL_LOG(LogTemp, Warning, TEXT("Synthesizing Niagara source strategy stack for: %s"), *system_path);

    // Load the Niagara system
    UNiagaraSystem* NiagaraSystem = Cast<UNiagaraSystem>(StaticLoadObject(UNiagaraSystem::StaticClass(), nullptr, *system_path));
    if (!NiagaraSystem)
    {
        return FString(TEXT("Failed to load Niagara system: %s")) % *system_path;
    }

    // Set the source strategy
    NiagaraSystem->SetSourceStrategy(source_strategy);

    // Apply parameters
    for (const auto& Param : parameters)
    {
        NiagaraSystem->SetNiagaraVariableFloat(Param.Key, FCString::Atof(*Param.Value));
    }

    // Save the system if requested
    if (save)
    {
        FScopedTransaction Transaction(TEXT("Save Niagara System"));
        NiagaraSystem->MarkPackageDirty();
        FAssetRegistryModule& AssetRegistryModule = FModuleManager::LoadModuleChecked<FAssetRegistryModule>(TEXT("AssetRegistry"));
        AssetRegistryModule.Get().UpdateAsset(NiagaraSystem);
